    { id: "coke", name: "에드워드 코크", original: "Edward Coke", years: "1552–1634", era: "early-modern", schools: ["historical", "constitutional"], role: "보통법의 인공적 이성", claim: "오랜 판례와 법률가의 전문적 추론으로 형성된 보통법이 왕의 자의적 권력도 제한한다고 보았다.", works: ["《영국법 총론》 Institutes", "《판례집》 Reports"], relations: ["논쟁 · 코크 ↔ 홉스", "영향 · 법의 지배와 보통법 헌정주의"] },
    { id: "hobbes", name: "토머스 홉스", original: "Thomas Hobbes", years: "1588–1679", era: "early-modern", schools: ["positivism", "constitutional"], role: "주권과 법의 권위", claim: "평화를 가능하게 하는 통일된 주권자의 권위에서 시민법의 강제력과 해석의 최종성을 찾았다.", works: ["《리바이어던》", "《법학자와 철학자의 대화》"], relations: ["논쟁 · 코크의 보통법 우위론 비판", "영향 · 벤담·오스틴의 명령설"] },
    { id: "locke", name: "존 로크", original: "John Locke", years: "1632–1704", era: "early-modern", schools: ["natural", "constitutional"], role: "자연권과 제한정부", claim: "생명·자유·재산의 권리를 보호하기 위해 정부가 성립하며 권리 침해 시 저항이 가능하다고 보았다.", works: ["《통치론》", "《관용에 관한 편지》"], relations: ["대립 · 홉스의 강한 주권론과 대비", "영향 · 입헌주의와 근대 권리 선언"] },
    { id: "montesquieu", name: "몽테스키외", original: "Montesquieu", years: "1689–1755", era: "early-modern", schools: ["constitutional", "social"], role: "법의 정신과 권력분립", claim: "법을 사회의 조건·정체와 관련해 비교하고 권력이 권력을 견제하는 제도구조를 제시했다.", works: ["《법의 정신》"], relations: ["영향 · 근대 헌법의 권력분립", "방법 · 비교법·법사회학의 선구"] },
    { id: "rousseau", name: "장자크 루소", original: "Jean-Jacques Rousseau", years: "1712–1778", era: "early-modern", schools: ["constitutional", "justice"], role: "일반의지와 자기입법", claim: "시민이 공동의 법을 스스로 만드는 인민주권에서 자유와 정치적 복종의 양립을 찾았다.", works: ["《사회계약론》", "《인간 불평등 기원론》"], relations: ["영향 · 칸트와 민주적 정당성론", "대립 · 대표·부분이익과 일반의지"] },
    { id: "beccaria", name: "체사레 베카리아", original: "Cesare Beccaria", years: "1738–1794", era: "early-modern", schools: ["justice", "constitutional"], role: "근대 형벌의 한계", claim: "고문과 자의적·과도한 형벌을 비판하고 명확성·비례성·확실성·인도주의를 요구했다.", works: ["《범죄와 형벌》"], relations: ["계승 · 계몽주의·사회계약", "영향 · 죄형법정주의와 형법개혁"] },
    { id: "kant", name: "임마누엘 칸트", original: "Immanuel Kant", years: "1724–1804", era: "early-modern", schools: ["justice", "natural", "constitutional"], role: "외적 자유의 법", claim: "각자의 외적 자유가 보편적 자유의 법칙 아래 함께 존재할 수 있는 조건을 법의 핵심으로 보았다.", works: ["《도덕형이상학》 법론", "《영구평화론》"], relations: ["영향 · 루소의 자유와 자기입법", "영향 · 헤겔·롤스·라드브루흐"] },
    { id: "bentham", name: "제러미 벤담", original: "Jeremy Bentham", years: "1748–1832", era: "early-modern", schools: ["positivism", "economic"], role: "공리주의와 법전편찬", claim: "법을 사회적 효용으로 평가하고 불명확한 판례법과 자연권 수사를 비판하며 공개된 법전을 요구했다.", works: ["《도덕과 입법의 원리 서설》", "《정부론 단편》"], relations: ["비판 · 블랙스톤의 보통법론", "영향 · 오스틴과 법경제학의 공리적 계보"] },
    { id: "hegel", name: "게오르크 헤겔", original: "G. W. F. Hegel", years: "1770–1831", era: "nineteenth", schools: ["justice", "constitutional", "critical"], role: "제도 속에서 실현되는 자유", claim: "추상적 권리–도덕성–인륜성의 발전 속에서 자유가 가족·시민사회·국가의 제도로 현실화된다고 보았다.", works: ["《법철학 강요》"], relations: ["계승·비판 · 칸트의 추상적 자유", "영향 · 마르크스와 현대 인정·제도 이론"] },
    { id: "austin", name: "존 오스틴", original: "John Austin", years: "1790–1859", era: "nineteenth", schools: ["positivism"], role: "고전적 명령설", claim: "실정법을 정치적 우월자가 제재를 배경으로 내린 일반적 명령으로 분석하고 법의 존재와 가치를 구별했다.", works: ["《법리학의 범위가 결정되다》"], relations: ["계승 · 벤담", "비판 · 하트가 명령·습관·주권 개념을 재구성"] },
    { id: "thibaut", name: "안톤 티보", original: "A. F. J. Thibaut", years: "1772–1840", era: "nineteenth", schools: ["historical", "roman"], role: "통일 민법전 주장", claim: "분열된 독일 법질서를 합리적이고 통일된 민법전으로 조속히 정리해야 한다고 주장했다.", works: ["《독일 일반 민법전의 필요성에 관하여》"], relations: ["논쟁 · 티보 ↔ 사비니 법전편찬논쟁"] },
    { id: "savigny", name: "프리드리히 사비니", original: "F. C. von Savigny", years: "1779–1861", era: "nineteenth", schools: ["historical", "roman"], role: "역사법학", claim: "법은 입법자가 한 번에 설계하는 것이 아니라 민족의 공동의식과 법률가의 작업 속에서 유기적으로 성장한다고 보았다.", works: ["《입법과 법학에 관한 우리 시대의 사명》", "《현대로마법 체계》"], relations: ["논쟁 · 티보의 즉시 법전편찬론 반대", "학파 · 사비니 → 푸흐타 → 판덱텐법학"] },
    { id: "puchta", name: "게오르크 푸흐타", original: "Georg Friedrich Puchta", years: "1798–1846", era: "nineteenth", schools: ["historical", "roman"], role: "개념의 계보와 체계", claim: "역사적으로 형성된 법을 개념의 위계와 논리적 연관으로 체계화하여 판덱텐법학의 방법을 강화했다.", works: ["《관습법론》", "《판덱텐 교과서》"], relations: ["학파 · 사비니의 후계", "영향 · 개념법학과 빈트샤이트"] },
    { id: "windscheid", name: "베른하르트 빈트샤이트", original: "Bernhard Windscheid", years: "1817–1892", era: "nineteenth", schools: ["historical", "roman"], role: "판덱텐법학의 완성", claim: "로마 사법을 정교한 개념체계로 재구성해 독일 민법학과 독일민법전의 학설적 토대를 제공했다.", works: ["《판덱텐법 교과서》"], relations: ["계승 · 사비니·푸흐타", "비판 · 예링과 자유법론이 형식성을 비판"] },
    { id: "jhering", name: "루돌프 폰 예링", original: "Rudolf von Jhering", years: "1818–1892", era: "nineteenth", schools: ["social", "historical"], role: "목적과 이익의 법학", claim: "법은 논리적 개념의 자기전개가 아니라 사회적 목적과 이익을 실현하기 위한 투쟁의 산물이라고 전환했다.", works: ["《법의 목적》", "《권리를 위한 투쟁》"], relations: ["전환 · 개념법학 내부에서 목적법학으로", "영향 · 이익법학·법사회학·자유법론"] },
    { id: "ehrlich", name: "오이겐 에를리히", original: "Eugen Ehrlich", years: "1862–1922", era: "nineteenth", schools: ["social"], role: "살아 있는 법", claim: "법의 중심은 국가가 만든 조문만이 아니라 결사·관행·사회질서 속에서 실제로 작동하는 규범이라고 보았다.", works: ["《법사회학의 기초》"], relations: ["계승 · 예링의 사회적 법관", "영향 · 법사회학과 법다원주의"] },
    { id: "marx", name: "카를 마르크스", original: "Karl Marx", years: "1818–1883", era: "nineteenth", schools: ["critical"], role: "법과 계급·생산관계", claim: "형식적 자유와 평등을 경제적 생산관계·계급권력과 분리해 이해할 수 없다고 비판했다.", works: ["《자본론》", "《헤겔 법철학 비판》"], relations: ["비판적 계승 · 헤겔", "영향 · 파슈카니스·CLS·비판법학"] },
    { id: "holmes", name: "올리버 웬들 홈스", original: "Oliver Wendell Holmes Jr.", years: "1841–1935", era: "modern", schools: ["realism", "social"], role: "경험과 예측으로서의 법", claim: "법의 생명은 논리가 아니라 경험이며, 실무에서는 법원이 실제 무엇을 할지 예측하는 관점이 중요하다고 보았다.", works: ["《보통법》", "〈법의 길〉"], relations: ["비판 · 형식주의·기계적 법적용", "영향 · 파운드와 미국 법현실주의"] },
    { id: "pound", name: "로스코 파운드", original: "Roscoe Pound", years: "1870–1964", era: "modern", schools: ["social", "realism"], role: "사회공학으로서의 법", claim: "책 속의 법과 행동 속의 법을 구별하고 상충하는 사회적 이익을 조정하는 제도로 법을 보았다.", works: ["《사회학적 법학 개론》", "〈책 속의 법과 행동 속의 법〉"], relations: ["계승 · 예링·홈스", "영향 · 미국 법현실주의와 사회법학"] },
    { id: "llewellyn", name: "칼 르웰린", original: "Karl Llewellyn", years: "1893–1962", era: "modern", schools: ["realism"], role: "제도 행동과 상황감각", claim: "법관과 법기관이 실제로 어떻게 행동하는지, 판례가 어떤 상황감각으로 작동하는지 관찰해야 한다고 주장했다.", works: ["《가시덤불》 The Bramble Bush", "《보통법 전통》"], relations: ["계승 · 홈스·파운드", "영향 · 법현실주의와 경험법학"] },
    { id: "frank", name: "제롬 프랭크", original: "Jerome Frank", years: "1889–1957", era: "modern", schools: ["realism"], role: "사실인정의 불확실성", claim: "규칙뿐 아니라 증언·사실인정·법관의 심리도 판결의 불확실성을 만든다고 강조했다.", works: ["《법과 현대정신》", "《재판과 사실》"], relations: ["학파 · 미국 법현실주의", "차이 · 르웰린보다 사실회의주의를 강하게 강조"] },
    { id: "kelsen", name: "한스 켈젠", original: "Hans Kelsen", years: "1881–1973", era: "modern", schools: ["positivism", "constitutional"], role: "순수법학과 규범 위계", claim: "법학을 정치·도덕·사회학에서 방법적으로 분리하고, 하위 규범의 효력을 상위 규범과 기본규범으로 설명했다.", works: ["《순수법학》", "《법과 국가의 일반이론》"], relations: ["논쟁 · 켈젠 ↔ 슈미트, 헌법의 수호자", "영향 · 현대 규범주의·헌법재판 이론"] },
    { id: "schmitt", name: "카를 슈미트", original: "Carl Schmitt", years: "1888–1985", era: "modern", schools: ["constitutional", "critical"], role: "결단과 예외상태", claim: "정상 규칙이 멈추는 예외상태를 누가 결정하는지가 주권과 법질서의 정치적 기반을 드러낸다고 보았다.", works: ["《정치신학》", "《헌법론》"], relations: ["논쟁 · 켈젠의 규범주의와 충돌", "주의 · 나치 체제와의 결탁을 함께 읽어야 함"] },
    { id: "radbruch", name: "구스타프 라드브루흐", original: "Gustav Radbruch", years: "1878–1949", era: "modern", schools: ["justice", "positivism", "constitutional"], role: "극단적 불법과 법", claim: "법적 안정성을 중시하되, 정의와 평등을 의도적으로 극단적으로 부정하는 법은 법으로서의 성격을 잃을 수 있다고 보았다.", works: ["《법철학》", "〈법률적 불법과 초법률적 법〉"], relations: ["영향 · 칸트·신칸트주의", "쟁점 · 나치 이후 악법과 법적 안정성"] },
    { id: "pashukanis", name: "예브게니 파슈카니스", original: "Evgeny Pashukanis", years: "1891–1937", era: "modern", schools: ["critical"], role: "상품형태와 법형태", claim: "자유롭고 평등한 법적 주체의 형식을 자본주의 상품교환 관계와 연결해 분석했다.", works: ["《법의 일반이론과 마르크스주의》"], relations: ["계승 · 마르크스의 정치경제 비판", "영향 · 마르크스주의 법이론"] },
    { id: "fuller", name: "론 풀러", original: "Lon L. Fuller", years: "1902–1978", era: "modern", schools: ["natural", "social"], role: "법의 내적 도덕성", claim: "일반성·공표·비소급·명료성·무모순·실행가능성·안정성·공식행동의 일치가 법다운 법의 조건이라고 보았다.", works: ["《법의 도덕성》", "〈법실증주의와 법에 대한 충실성〉"], relations: ["직접 논쟁 · 풀러 ↔ 하트", "영향 · 법의 지배와 절차적 자연법"] },
    { id: "hart", name: "H. L. A. 하트", original: "H. L. A. Hart", years: "1907–1992", era: "modern", schools: ["positivism"], role: "1차·2차 규칙의 결합", claim: "법체계를 의무를 부과하는 1차 규칙과 승인·변경·재판을 가능하게 하는 2차 규칙의 결합으로 설명했다.", works: ["《법의 개념》", "《법, 자유와 도덕》"], relations: ["비판 · 오스틴의 명령설", "논쟁 · 풀러·데블린·드워킨", "지도 · 라즈와 피니스의 박사 지도"] },
    { id: "devlin", name: "패트릭 데블린", original: "Patrick Devlin", years: "1905–1992", era: "modern", schools: ["constitutional"], role: "공동도덕의 법적 보호", claim: "사회의 공유 도덕이 붕괴하면 공동체도 해체될 수 있으므로 일정한 도덕적 해악을 법으로 규제할 수 있다고 주장했다.", works: ["《도덕의 강제》"], relations: ["직접 논쟁 · 데블린 ↔ 하트", "쟁점 · 자유주의의 위해원칙과 도덕주의"] },
    { id: "dworkin", name: "로널드 드워킨", original: "Ronald Dworkin", years: "1931–2013", era: "contemporary", schools: ["interpretivism", "constitutional", "justice"], role: "원리와 통합성으로서의 법", claim: "법은 규칙뿐 아니라 권리와 원리를 포함하며, 판결은 제도사를 가장 잘 설명하고 정당화하는 통합적 해석이어야 한다고 보았다.", works: ["《권리를 진지하게 받아들이기》", "《법의 제국》"], relations: ["비판 · 하트의 규칙론과 재량론", "논쟁 · 왈드론의 사법심사 비판", "계승 · 하트의 옥스퍼드 석좌 후임"] },
    { id: "raz", name: "조지프 라즈", original: "Joseph Raz", years: "1939–2022", era: "contemporary", schools: ["positivism"], role: "배타적 실증주의와 권위", claim: "법은 도덕 판단과 독립된 사회적 원천으로 식별되어야 권위가 사람의 기초 이유를 매개하는 서비스 기능을 할 수 있다고 보았다.", works: ["《실천이성과 규범》", "《법의 권위》"], relations: ["사제 · 하트의 박사 제자", "분기 · 포용적 실증주의와 배타적 실증주의"] },
    { id: "finnis", name: "존 피니스", original: "John Finnis", years: "1940–", era: "contemporary", schools: ["natural", "justice"], role: "기본적 선과 실천적 합리성", claim: "생명·지식·놀이·심미·우정·실천적 합리성·종교 같은 기본적 선에서 법과 공동선의 이유를 재구성했다.", works: ["《자연법과 자연권》"], relations: ["사제 · 하트의 박사 제자", "계승 · 아퀴나스 자연법의 현대적 재구성"] },
    { id: "alexy", name: "로베르트 알렉시", original: "Robert Alexy", years: "1945–", era: "contemporary", schools: ["interpretivism", "constitutional", "natural"], role: "원리·형량·비실증주의", claim: "원리를 가능한 한 최대한 실현되어야 하는 최적화 명령으로 보고 기본권 충돌을 비례성과 형량의 구조로 설명했다.", works: ["《법적 논증이론》", "《기본권 이론》", "《법 개념과 법 효력》"], relations: ["영향 · 드워킨의 규칙/원리 구별", "대립 · 법과 도덕의 필연적 연결을 부정하는 실증주의"] },
    { id: "rawls", name: "존 롤스", original: "John Rawls", years: "1921–2002", era: "contemporary", schools: ["justice", "constitutional"], role: "공정으로서의 정의", claim: "무지의 베일 뒤 원초적 입장에서 동등한 자유와 가장 불리한 사람에게도 이익이 되는 제도를 선택한다고 보았다.", works: ["《정의론》", "《정치적 자유주의》"], relations: ["계승 · 칸트적 자율과 사회계약", "영향 · 현대 헌법·분배정의 논쟁"] },
    { id: "habermas", name: "위르겐 하버마스", original: "Jürgen Habermas", years: "1929–", era: "contemporary", schools: ["constitutional", "critical"], role: "담론과 민주적 정당성", claim: "강제되는 법의 사실성과 정당화 가능한 타당성을 민주적 의사소통으로 연결하고 인권과 인민주권의 공동기원을 주장했다.", works: ["《사실성과 타당성 사이》"], relations: ["영향 · 칸트·헤겔·비판이론", "대화 · 드워킨·롤스와 권리·민주주의 문제 공유"] },
    { id: "waldron", name: "제러미 왈드론", original: "Jeremy Waldron", years: "1953–", era: "contemporary", schools: ["constitutional", "justice"], role: "입법의 존엄과 불일치", claim: "권리에 대한 합리적 불일치가 지속되는 사회에서는 선출된 입법부의 동등한 참여가 강한 사법심사보다 중요할 수 있다고 본다.", works: ["《법과 불일치》", "《입법의 존엄》"], relations: ["비판 · 드워킨식 권리론과 강한 사법심사", "쟁점 · 법원과 민주적 입법의 정당성"] },
    { id: "coase", name: "로널드 코스", original: "Ronald Coase", years: "1910–2013", era: "contemporary", schools: ["economic"], role: "거래비용과 권리배분", claim: "거래비용의 존재와 권리의 초기 배분이 분쟁 해결과 자원 사용에 어떤 영향을 주는지 분석했다.", works: ["〈사회적 비용의 문제〉"], relations: ["영향 · 현대 법경제학", "분기 · 칼라브레시·포스너의 제도 분석"] },
    { id: "calabresi", name: "귀도 칼라브레시", original: "Guido Calabresi", years: "1932–", era: "contemporary", schools: ["economic"], role: "사고비용과 불법행위법", claim: "사고·예방·행정 비용을 함께 보고 손해를 누가 부담해야 사회적 비용이 줄어드는지 분석했다.", works: ["《사고의 비용》"], relations: ["영향 · 코스와 함께 현대 법경제학 형성", "차이 · 포스너보다 분배·제도 선택을 폭넓게 고려"] },
    { id: "posner", name: "리처드 포스너", original: "Richard Posner", years: "1939–", era: "contemporary", schools: ["economic"], role: "법의 경제분석", claim: "법규가 유인과 행동을 바꾸는 효과를 분석하고 효율성을 광범위한 법영역의 설명·평가 기준으로 사용했다.", works: ["《법의 경제분석》", "《법학의 문제들》"], relations: ["계승 · 벤담·코스", "대립 · 권리의 우선성과 효율 중심 평가"] },
    { id: "foucault", name: "미셸 푸코", original: "Michel Foucault", years: "1926–1984", era: "contemporary", schools: ["critical"], role: "규율권력과 주체 형성", claim: "법적 금지와 주권만이 아니라 감옥·병원·학교의 관찰·분류·정상화가 근대 권력을 구성한다고 분석했다.", works: ["《감시와 처벌》", "《성의 역사》"], relations: ["비판 · 법·주권 중심의 권력관", "영향 · 비판법학·범죄학·젠더 법이론"] },
    { id: "kennedy", name: "던컨 케네디", original: "Duncan Kennedy", years: "1942–", era: "contemporary", schools: ["critical"], role: "법의 정치성과 위계", claim: "사법의 교리와 법학교육이 중립적 논리처럼 보이면서도 정치적 선택과 사회적 위계를 재생산할 수 있다고 비판했다.", works: ["〈법학교육과 위계의 재생산〉", "《법적 추론의 비판》"], relations: ["계승 · 법현실주의와 마르크스주의 비판", "학파 · 비판법학 CLS"] },
    { id: "unger", name: "로베르토 웅거", original: "Roberto Mangabeira Unger", years: "1947–", era: "contemporary", schools: ["critical"], role: "제도적 상상력과 비결정성", claim: "현존 법제도를 필연적인 것으로 보는 형식주의를 비판하고 사회관계를 다시 설계할 제도적 대안을 강조했다.", works: ["《비판법학 운동》"], relations: ["학파 · CLS의 중심 이론가", "비판 · 법의 객관성·필연성 주장"] },
    { id: "bell", name: "데릭 벨", original: "Derrick Bell", years: "1930–2011", era: "contemporary", schools: ["critical"], role: "인종과 법의 구조", claim: "형식적 평등 선언만으로 인종적 지배가 사라지지 않으며, 권리의 진전도 지배집단의 이해와 교차할 때 제한적으로 나타날 수 있다고 분석했다.", works: ["《인종, 인종주의와 미국법》", "《우물 바닥의 얼굴들》"], relations: ["계승·비판 · 민권법과 CLS", "영향 · 비판인종이론 CRT"] },
    { id: "crenshaw", name: "킴벌리 크렌쇼", original: "Kimberlé Crenshaw", years: "1959–", era: "contemporary", schools: ["critical"], role: "교차성과 비판인종이론", claim: "인종·성별·계급의 결합에서 생기는 차별은 단일 범주 중심의 법리로 포착되지 않을 수 있음을 교차성으로 설명했다.", works: ["〈인종과 성의 교차를 탈주변화하기〉", "〈주변부를 지도하기〉"], relations: ["계승 · 데릭 벨과 비판인종이론", "비판 · 단일축 차별법리와 일부 페미니즘"] },
    { id: "mackinnon", name: "캐서린 매키넌", original: "Catharine A. MacKinnon", years: "1946–", era: "contemporary", schools: ["critical"], role: "성별 권력과 실질적 평등", claim: "형식적 성중립성이 현실의 지배관계를 가릴 수 있으며 성차별을 권력과 종속의 구조로 보아야 한다고 주장했다.", works: ["《국가의 페미니즘 이론을 향하여》", "《성희롱과 성차별》"], relations: ["영향 · 페미니즘 법학", "대화·긴장 · 평등법·표현의 자유·CRT"] },
    { id: "shapiro", name: "스콧 샤피로", original: "Scott J. Shapiro", years: "1967–", era: "contemporary", schools: ["positivism"], role: "법의 계획이론", claim: "복잡하고 반복되는 도덕·사회 문제를 함께 해결하기 위한 공유된 사회적 계획으로 법제도를 설명한다.", works: ["《합법성》 Legality"], relations: ["계승 · 하트의 사회적 규칙론", "논쟁 · 드워킨 이후 분석법철학의 재구성"] }
